contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // params: amount to deposit, amount to attempt to collect
    function run(uint depositAmt, uint collectAmt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmt)); require(depositAmt <= 1000000000000000000000000000000);
        // ensure this test contract has funds to deposit
        require(address(this).balance >= depositAmt);

        // ensure MinSum does not block collects by default: set to 0
        c.SetMinSum(0); if (__ESBMC_reverted()) return;

        // make an initial deposit so there is some balance to potentially collect
        c.Deposit{value: depositAmt}(); if (__ESBMC_reverted()) return;

        // read before values
        uint bal_before_pub = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint c_balance_before = address(c).balance;

        // attempt Collect and record whether it reverted
        bool reverted;
        c.Collect(collectAmt); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read after values
        uint bal_after_pub = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint c_balance_after = address(c).balance;

        // General rule:
        // - If Collect reverted then the public balance and contract ETH balance remain the same.
        // - If Collect succeeded then the public balance does not increase and the contract ETH balance does not increase (both <= their before values).
        assert(reverted ? (bal_after_pub == bal_before_pub && c_balance_after == c_balance_before)
                        : (bal_after_pub <= bal_before_pub && c_balance_after <= c_balance_before));
    }

    receive() external payable {}
}

