// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 depositAmt, uint256 collectAmt) internal {
        depositAmt = bound(depositAmt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmt);
        try c.SetMinSum(0) {} catch { return; }
        try c.Deposit{value: depositAmt}() {} catch { return; }
        uint256 bal_before_pub;
        try c.balances(address(this)) returns (uint256 __r) { bal_before_pub = __r; } catch { return; }
        uint c_balance_before = address(c).balance;
        bool reverted;
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 bal_after_pub;
        try c.balances(address(this)) returns (uint256 __r) { bal_after_pub = __r; } catch { return; }
        uint c_balance_after = address(c).balance;
        assertTrue(reverted ? (bal_after_pub == bal_before_pub && c_balance_after == c_balance_before)
                        : (bal_after_pub <= bal_before_pub && c_balance_after <= c_balance_before));
    }

    function testFuzz_run(uint256 depositAmt, uint256 collectAmt) public {
        _run(depositAmt, collectAmt);
    }

    receive() external payable {}
}
